<?php use App\Models\Ticket; ?>
<div class="dashboard-kpis"><?php foreach([['completed','Terminés','Ces 7 derniers jours','check','mint'],['updated','Mis à jour','Ces 7 derniers jours','clock','lavender'],['created','Nouveaux tickets','Ces 7 derniers jours','plus','blue'],['upcoming','Échéances proches','Ces 7 prochains jours','flag','peach']] as [$k,$label,$hint,$i,$tone]): ?><a class="kpi-card" href="/list?project=<?= (int)$project['id'] ?><?= $k==='completed'?'&status=done':($k==='upcoming'?'&due_before='.gmdate('Y-m-d',time()+7*86400).'&hide_done=1':($k==='created'?'&jql='.rawurlencode('created >= "'.gmdate('Y-m-d',time()-7*86400).'"'):'&jql='.rawurlencode('updated >= "'.gmdate('Y-m-d',time()-7*86400).'"'))) ?>"><div class="kpi-top"><span class="kpi-symbol <?= e($tone) ?>"><?= icon($i) ?></span><?= icon('external') ?></div><strong class="kpi-number"><?= (int)$kpis[$k] ?></strong><div class="kpi-label"><?= e($label) ?></div><small><?= e($hint) ?></small></a><?php endforeach; ?></div>
<div class="dashboard-grid"><section class="panel status-panel"><div class="panel-header"><div><h2>Le travail, en un regard</h2><p>Chaque étape raconte une progression.</p></div><a class="icon-button" href="/board" aria-label="Ouvrir le tableau"><?= icon('arrow') ?></a></div><div class="status-summary"><div class="donut" data-donut='<?= e(json_encode($stats['status'],JSON_THROW_ON_ERROR)) ?>'><svg viewBox="0 0 120 120" aria-label="Répartition des tickets par état"><circle cx="60" cy="60" r="46" class="donut-base"/></svg><div><strong><?= $count ?></strong><span>tickets au total</span></div></div><div class="status-legend"><?php foreach(Ticket::STATUSES as $s=>$label): $n=0; foreach($stats['status'] as $row) if($row['label']===$s) $n=(int)$row['n']; ?><a href="/list?project=<?= (int)$project['id'] ?>&status=<?= e($s) ?>"><span class="legend-dot status-<?= e($s) ?>"></span><?= e($label) ?><strong><?= $n ?></strong></a><?php endforeach; ?></div></div><div class="panel-bottom"><span><?= (int)$kpis['overdue'] ?> ticket(s) en retard</span><a href="/list?project=<?= (int)$project['id'] ?>">Voir les tickets <?= icon('arrow') ?></a></div></section>
<section class="panel" id="recent"><div class="panel-header"><div><h2>Le fil de l’équipe</h2><p>Les derniers petits et grands pas.</p></div><span class="live-dot"></span></div><div class="activity-feed"><?php foreach(array_slice($activity,0,5) as $a): ?><div class="activity-item"><?= avatar($a['name']??'Externe','small', $a['user_id'] ? (int)$a['user_id'] : null) ?><div><p><strong><?= e($a['name']??'Un utilisateur externe') ?></strong> <?= e($a['message']) ?></p><?php if($a['ticket_id']): ?><a href="<?= e(ticket_url((int)$a['ticket_id'])) ?>"><?= e($a['project_key'].'-'.$a['number']) ?></a><?php endif; ?><small><?= e((new DateTimeImmutable($a['created_at']))->format('d/m · H:i')) ?></small></div></div><?php endforeach; if(!$activity): ?><p class="muted">L’histoire commence avec votre premier ticket.</p><?php endif; ?></div><details class="activity-more"><summary>Voir toute l’activité <?= icon('down') ?></summary><?php foreach(array_slice($activity,5) as $a): ?><p><?= e($a['name']??'Externe') ?> <?= e($a['message']) ?> · <?= e($a['created_at']) ?></p><?php endforeach; ?></details></section>
<section class="panel"><div class="panel-header"><div><h2>Les bonnes priorités</h2><p>Concentrez l’énergie là où elle compte.</p></div><span class="kpi-symbol peach"><?= icon('flag') ?></span></div><?php bars($stats['priority'],Ticket::PRIORITIES,'priority'); ?></section><section class="panel"><div class="panel-header"><div><h2>Une charge équilibrée</h2><p>Répartition des tickets dans l’équipe.</p></div><span class="kpi-symbol blue"><?= icon('user') ?></span></div><?php bars($stats['assignee'],[],'assignee'); ?><p class="help-text">Répartition en nombre de tickets, sans estimation horaire.</p></section>
<section class="panel"><div class="panel-header"><div><h2>Chaque forme de travail</h2><p>Des petits détails aux grandes idées.</p></div></div><?php bars($stats['type'],Ticket::TYPES,'type'); ?></section><section class="panel epic-panel"><div class="panel-header"><div><h2>Les grands caps</h2><p>Avancement de vos Epics.</p></div><span class="kpi-symbol lavender"><?= icon('spark') ?></span></div><?php $epics=App\Core\DB::all("SELECT t.id,t.number,t.title,COUNT(c.id) total,SUM(c.status='done') done FROM tickets t LEFT JOIN tickets c ON c.parent_id=t.id AND c.archived=0 WHERE t.project_id=? AND t.type='epic' AND t.archived=0 GROUP BY t.id ORDER BY t.id DESC LIMIT 5",[$project['id']]); foreach($epics as $epic): ?><a class="epic-row" href="<?= e(ticket_url((int)$epic['id'])) ?>"><span class="type-icon type-epic">ϟ</span><div><strong><?= e($epic['title']) ?></strong><progress value="<?= (int)$epic['done'] ?>" max="<?= max(1,(int)$epic['total']) ?>"></progress><small><?= (int)$epic['done'] ?> / <?= (int)$epic['total'] ?> tickets terminés</small></div></a><?php endforeach; if(!$epics): ?><div class="mini-empty"><?= icon('spark') ?><p>Créez un Epic pour donner un cap à vos initiatives.</p></div><?php endif; ?></section></div>

<?php require ROOT.'/app/Views/partials/team-workload.php'; ?>
